const input=$json.body??$json;
const s=v=>String(v??'').trim();
const audit=input.audit??input;
const identity=audit.identity??input.identity??{};
const leadId=s(identity.lead_id);
const propertyId=s(identity.property_id);
const dealId=s(identity.deal_id);
const id=s(dealId||propertyId||leadId);
const requestId=s(audit.request_id??input.request_id);
const decision=audit.decision??input.decision??{};
const underwritingStatus=s(decision.status??input.status).toLowerCase();
const recommendedOffer=Number(decision.recommended_offer??input.recommended_offer);
const mao=Number(decision.mao??input.mao??recommendedOffer);
const evidenceQuality=audit.evidence_quality??input.evidence_quality??{};
const seller=audit.seller??input.seller??{};
const property=audit.property??input.property??{};
const exit=audit.exit_strategy??input.exit_strategy??{};
const motivation=s(seller.motivation??seller.motivation_level??input.motivation);
const timing=s(seller.timing??seller.timeline??input.timing);
const offerType=s(input.offer_type??exit.offer_type??'purchase_contract').toLowerCase();
const assignmentAllowed=input.assignment_allowed??exit.assignment_allowed??true;
const novationAllowed=input.novation_allowed??exit.novation_allowed??false;
const doubleCloseAllowed=input.double_close_allowed??exit.double_close_allowed??false;
const negotiationRoomPct=Math.max(0,Math.min(0.25,Number(input.negotiation_room_pct??seller.negotiation_room_pct??0.08)));
const minimumTarget=Number(input.minimum_target??decision.minimum_target??recommendedOffer);
const hardCeiling=Number.isFinite(mao)&&mao>0?mao:null;
const missing=[];
if(!leadId)missing.push('lead_id');
if(!propertyId&&!dealId)missing.push('property_or_deal_id');
if(!Number.isFinite(recommendedOffer)||recommendedOffer<=0)missing.push('recommended_offer');
if(!hardCeiling)missing.push('mao');
if(!underwritingStatus)missing.push('decision_status');
if(underwritingStatus&& !['approved','ready','proceed','approved_with_conditions'].includes(underwritingStatus))missing.push('underwriting_approval');
if(hardCeiling&&Number.isFinite(recommendedOffer)&&recommendedOffer>hardCeiling)missing.push('recommended_offer_exceeds_mao');
const baseOffer=Number.isFinite(recommendedOffer)&&hardCeiling?Math.min(recommendedOffer,hardCeiling):null;
const openingOffer=baseOffer?Math.min(baseOffer,Math.max(0,baseOffer*(1-negotiationRoomPct))):null;
const targetOffer=baseOffer?Math.min(baseOffer,Math.max(minimumTarget,baseOffer*(1-negotiationRoomPct/2))):null;
const spreadToMao=baseOffer&&hardCeiling?Math.max(0,hardCeiling-baseOffer):null;
const approvalRequired=missing.length>0||input.human_approval_required===true||baseOffer===null;
const strategyStatus=approvalRequired?'approval_required':'ready';
const rationale=[
'Offer strategy is derived from the approved underwriting decision.',
'MAO is a hard ceiling; no seller offer may exceed it.',
'Negotiation room is applied below the approved recommended offer and capped at 25%.',
motivation?'Seller motivation: '+motivation+'.':null,
timing?'Seller timing: '+timing+'.':null
].filter(Boolean).join(' ');
const strategy={
strategy_version:'offer-strategy.v1',
status:strategyStatus,
offer_type:offerType,
opening_offer:openingOffer,
target_offer:targetOffer,
recommended_offer:baseOffer,
mao_ceiling:hardCeiling,
negotiation_room_pct:negotiationRoomPct,
minimum_target:Number.isFinite(minimumTarget)?minimumTarget:null,
spread_to_mao:spreadToMao,
seller:{motivation:motivation||null,timing:timing||null},
exit_strategy:{assignment_allowed:!!assignmentAllowed,novation_allowed:!!novationAllowed,double_close_allowed:!!doubleCloseAllowed},
approval_required:approvalRequired,
rationale,
guardrails:{never_exceed_mao:true,never_negative_offer:true,underwriting_must_be_approved:true}
};
const strategyId='offer-strategy:'+s(id||'unknown')+':'+s(requestId||'unknown')+':v1';
const activity={
activity_type:'offer_strategy',
subject:'AI seller offer strategy '+strategyStatus,
body:[
'Offer strategy generated by Wholesaling OS.',
'Offer type: '+offerType,
'Opening offer: '+String(openingOffer??'not available'),
'Target offer: '+String(targetOffer??'not available'),
'Recommended offer: '+String(baseOffer??'not available'),
'MAO ceiling: '+String(hardCeiling??'not available'),
'Approval required: '+String(approvalRequired),
'Rationale: '+rationale
].join('\n'),
lead_id:leadId||null,
property_id:propertyId||null,
deal_id:dealId||null,
external_id:strategyId,
external_source:'wholesaling-os-offer-strategy',
metadata:{strategy_id:strategyId,request_id:requestId||null,underwriting_status:underwritingStatus,offer_strategy:strategy,evidence_quality:evidenceQuality}
};
return[{json:{
ok:missing.length===0&&strategyStatus==='ready',
status:strategyStatus,
strategy_id:strategyId,
request_id:requestId||null,
identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},
underwriting:{status:underwritingStatus,recommended_offer:recommendedOffer,mao:hardCeiling,evidence_quality:evidenceQuality},
offer_strategy:strategy,
crm_activity:activity,
missing_requirements:[...new Set(missing)],
next_workflow:strategyStatus==='ready'?'wf-035-offer-preparation':'human_review'
}}];
